-- DISPOSABLE PROJECT ONLY. Temporary scheduler harness for one synthetic job.
-- Do not install on production. The worker token is generated by the local test,
-- stored in Vault, and removed after the test. Never print or commit its value.
create or replace function public.start_disposable_dispatch_90s_http_test(
  p_job_id uuid, p_endpoint text, p_token text
) returns boolean
language plpgsql security definer set search_path = ''
as $$
declare
  v_name text := 'moovu_dispatch_90s_http_test';
  v_command text;
begin
  if auth.role() is distinct from 'service_role' then
    raise exception 'Trusted server role required';
  end if;
  if p_endpoint !~ '^https://[a-z0-9-]+[.]loca[.]lt/api/jobs/dispatch$' then
    raise exception 'Disposable endpoint required';
  end if;
  if p_token !~ '^[0-9a-f]{64}$' then
    raise exception 'Strong ephemeral worker token required';
  end if;
  if exists (select 1 from cron.job where jobname = v_name) then
    raise exception 'Disposable schedule already exists';
  end if;
  if not exists (
    select 1 from public.dispatch_jobs j
    join public.trips t on t.id = j.trip_id
    join public.customers c on c.id = t.customer_id
    join auth.users u on u.id = c.auth_user_id
    where j.id = p_job_id and j.status = 'pending'
      and j.job_type = 'recover'
      and u.email like 'dispatch-90-customer-%@example.com'
  ) then
    raise exception 'Pending synthetic recover job required';
  end if;
  perform vault.create_secret(p_token, 'moovu_dispatch_90s_http_test_token');
  v_command := format(
    'select net.http_post(url := %L, headers := jsonb_build_object(''Content-Type'', ''application/json'', ''x-dispatch-job-secret'', (select decrypted_secret from vault.decrypted_secrets where name = ''moovu_dispatch_90s_http_test_token'')), body := jsonb_build_object(''disposableTestJobId'', %L), timeout_milliseconds := 8000)',
    p_endpoint, p_job_id::text
  );
  perform cron.schedule(v_name, '10 seconds', v_command);
  return true;
end;
$$;

create or replace function public.stop_disposable_dispatch_90s_http_test()
returns boolean
language plpgsql security definer set search_path = ''
as $$
begin
  if auth.role() is distinct from 'service_role' then
    raise exception 'Trusted server role required';
  end if;
  if exists (select 1 from cron.job where jobname = 'moovu_dispatch_90s_http_test') then
    perform cron.unschedule('moovu_dispatch_90s_http_test');
  end if;
  delete from vault.secrets where name = 'moovu_dispatch_90s_http_test_token';
  return true;
end;
$$;

revoke all on function public.start_disposable_dispatch_90s_http_test(uuid, text, text)
  from public, anon, authenticated;
revoke all on function public.stop_disposable_dispatch_90s_http_test()
  from public, anon, authenticated;
grant execute on function public.start_disposable_dispatch_90s_http_test(uuid, text, text) to service_role;
grant execute on function public.stop_disposable_dispatch_90s_http_test() to service_role;

-- Full-window test variant: each tick selects only jobs for this synthetic trip.
create or replace function public.start_disposable_dispatch_90s_trip_http_test(
  p_trip_id uuid, p_endpoint text, p_token text
) returns boolean
language plpgsql security definer set search_path = ''
as $$
declare
  v_command text;
begin
  if auth.role() is distinct from 'service_role' then
    raise exception 'Trusted server role required';
  end if;
  if p_endpoint !~ '^https://[a-z0-9-]+[.]loca[.]lt/api/jobs/dispatch$'
    or p_token !~ '^[0-9a-f]{64}$' then
    raise exception 'Disposable endpoint and strong ephemeral token required';
  end if;
  if exists (select 1 from cron.job where jobname = 'moovu_dispatch_90s_http_test') then
    raise exception 'Disposable schedule already exists';
  end if;
  if not exists (
    select 1 from public.dispatch_matching_windows w
    join public.trips t on t.id = w.trip_id
    join public.customers c on c.id = t.customer_id
    join auth.users u on u.id = c.auth_user_id
    where w.trip_id = p_trip_id and w.state = 'SEARCHING'
      and u.email like 'dispatch-90-customer-%@example.com'
  ) then
    raise exception 'Searching synthetic trip required';
  end if;
  perform vault.create_secret(p_token, 'moovu_dispatch_90s_http_test_token');
  v_command := format(
    'select net.http_post(url := %L, headers := jsonb_build_object(''Content-Type'', ''application/json'', ''x-dispatch-job-secret'', (select decrypted_secret from vault.decrypted_secrets where name = ''moovu_dispatch_90s_http_test_token'')), body := jsonb_build_object(''disposableTestTripId'', %L), timeout_milliseconds := 8000)',
    p_endpoint, p_trip_id::text
  );
  -- Poll faster than the ten-second offer slots so an in-flight expiry job
  -- cannot consume the only worker opportunity in a slot.
  perform cron.schedule('moovu_dispatch_90s_http_test', '5 seconds', v_command);
  return true;
end;
$$;
revoke all on function public.start_disposable_dispatch_90s_trip_http_test(uuid, text, text)
  from public, anon, authenticated;
grant execute on function public.start_disposable_dispatch_90s_trip_http_test(uuid, text, text) to service_role;
